const items = $input.all();

// 1. የቴክ እና የሶፍትዌር ቁልፍ ቃላት
const techKeywords = [
  'software', 'developer', 'engineer', 'frontend', 'backend', 'fullstack',
  'web', 'mobile', 'android', 'ios', 'flutter', 'react', 'python',
  'javascript', 'typescript', 'node', 'java', 'golang', 'c++', 'c#',
  'data', 'ai', 'machine learning', 'cloud', 'devops', 'qa', 'tech'
];

// 2. መወገድ ያለባቸው ከቴክ ውጭ የሆኑ ስራዎች (Exclude non-tech)
const excludeKeywords = [
  'human resources', 'recruiter', 'care navigator', 'nurse', 'medical', 
  'sales representative', 'customer service', 'receptionist'
];

const techInternships = items.filter(item => {
  const json = item.json;
  if (!json.position) return false;

  const title = (json.position || '').toLowerCase();
  const tags = (json.tags || []).map(t => String(t).toLowerCase());
  const allText = title + ' ' + tags.join(' ');

  // ከቴክ ውጭ ከሆኑ ማለፍ (Skip)
  const isExcluded = excludeKeywords.some(ex => title.includes(ex));
  if (isExcluded) return false;

  // ቴክ መሆኑን ማረጋገጥ
  const isTech = techKeywords.some(kw => allText.includes(kw));

  // ኢንተርንሺፕ ወይም ጀማሪ መሆኑን ማረጋገጥ
  const isInternship = title.includes('intern') || 
                       tags.includes('internship') || 
                       tags.includes('intern') ||
                       title.includes('junior') ||
                       title.includes('trainee');

  return isTech && isInternship;
});

// የተገኙትን ንፁህ የቴክ ስራዎች መውሰድ (እስከ 3 ስራዎች)
return techInternships.slice(0, 3);
